export const commonOperations=["ingestion","tasks","detail","board","overview","tracking","events","activity"] as const;
export const changedOperations=["runs","run","tracking.run","registration","close","tracking.tasks","tracking.board"] as const;
export type Operation=typeof commonOperations[number]|typeof changedOperations[number];
export type RequestDeclaration={id:string;source:"base"|"head";operation:string;endpoint:string;method:"GET"|"POST";repetition:number;fixture:string;warmup:boolean;ordinal:number;key:string;role:"reporter"|"operator";expectedStatus:200|201;body?:unknown};
export type LoadFixture={id:string;source:"head";repetition:number;dir:string;facts:Awaited<ReturnType<typeof seedPerformance>>;events:Planned[];targets:ReturnType<typeof targets>;audit:ReturnType<typeof stoppedAudit>};
export async function prepareLoad(root:string,repetition:number):Promise<LoadFixture>{
 const id=`load-${repetition}`,dir=join(root,id);mkdirSync(dir,{mode:0o700});
 const facts=await seedPerformance(dir,{tasks:1000,events:10000,producers:10},Date.now()-3600000),events=plan(facts.runs,repetition),observations=targets(events),audit=stoppedAudit(dir,join(root,id+"-audit"),true);
 assert.equal(audit.rows.tasks.length,1000);assert.equal(audit.rows.run_events.length,10000);assert.equal(events.length,7000);assert.equal(observations.length,128);
 const fixture={id,source:"head" as const,repetition,dir,facts,events,targets:observations,audit};privateSave(root,id+"-prepared.json",fixture);return fixture;
}
export function publicOperations(facts:Awaited<ReturnType<typeof seedPerformance>>){
 return {ingestion:`/api/v1/runs/${facts.runs[0]}/events`,tasks:`/api/v1/tasks?projectId=${facts.projectId}&limit=50`,detail:`/api/v1/tasks/${facts.tasks[0]}`,board:`/api/v1/projects/${facts.projectId}/board?limit=50`,overview:"/api/v1/overview?timezone=UTC",tracking:`/api/v1/tracking/runs?projectId=${facts.projectId}&limit=50`,events:`/api/v1/runs/${facts.historic[0]}/events?limit=50`,activity:`/api/v1/activity?projectId=${facts.projectId}&limit=50`,runs:`/api/v1/runs?projectId=${facts.projectId}&limit=50`,run:`/api/v1/runs/${facts.historic[0]}`,"tracking.run":`/api/v1/tracking/runs/${facts.historic[0]}`,registration:"/api/v1/runs",close:"/api/v1/runs/{predeclaredStaleRunId}/close","tracking.tasks":`/api/v1/tracking/tasks?projectId=${facts.projectId}&limit=50`,"tracking.board":`/api/v1/tracking/projects/${facts.projectId}/board?limit=50`};
}
export function declareComparisons(facts:Awaited<ReturnType<typeof seedPerformance>>,repetition:number,staleRuns:string[]){
 assert.equal(staleRuns.length,110);const endpoints=publicOperations(facts),rows:RequestDeclaration[]=[];
 for(let ordinal=0;ordinal<110;ordinal++)for(const operation of [...commonOperations,...changedOperations]){
  const producer=ordinal%10,sequence=Math.floor(ordinal/10)+1,key=randomUUID();
  const body=operation==="registration"?{id:randomUUID(),projectId:facts.projectId,agentId:facts.agents[0],purpose:"planning"}:operation==="close"?{expectedVersion:1,reason:"Synthetic W04 stale tracking closure; no process action"}:operation==="ingestion"?{schemaVersion:1,eventId:randomUUID(),runId:facts.runs[producer],sequence,type:sequence===1?"run.started":"run.heartbeat",occurredAt:"2026-10-12T00:00:00.000Z",payload:{}}:undefined;
  const endpoint=operation==="close"?`/api/v1/runs/${staleRuns[ordinal]}/close`:operation==="ingestion"?`/api/v1/runs/${facts.runs[producer]}/events`:endpoints[operation];
  for(const source of repetition%2?["base","head"] as const:["head","base"] as const)rows.push({id:`${operation}-${source}-${repetition}-${ordinal}`,source,operation,endpoint,method:["ingestion","registration","close"].includes(operation)?"POST":"GET",repetition,fixture:`comparison-${source}-${repetition}`,warmup:ordinal<10,ordinal,key,role:operation==="close"?"operator":"reporter",expectedStatus:["ingestion","registration"].includes(operation)?201:200,...(body?{body}: {})});
 }
 return rows;
}

import { spawn } from "node:child_process";
import { existsSync,cpSync,readFileSync,readdirSync,writeFileSync,chmodSync,lstatSync } from "node:fs";
